for (const [language, entries] of Object.entries(catalogCompletionTranslations)) {
  const catalog = translationCatalogs[language];
  if (!catalog) continue;
  for (const [key, value] of Object.entries(entries)) {
    const path = key.split(".");
    const leaf = path.pop();
    let node = catalog;
    for (const part of path) {
      const child = node[part];
      node[part] = child && typeof child === "object" ? { ...child } : {};
      node = node[part];
    }
    node[leaf] = value;
  }
}

function readStorage(key) {
  try {
    return globalThis.localStorage?.getItem(key) ?? null;
  } catch {
    return null;
  }
}

function writeStorage(key, value) {
  try {
    globalThis.localStorage?.setItem(key, value);
  } catch {
    // Storage can be unavailable in privacy modes; language still changes for the current session.
  }
}

export function normalizeLanguage(value) {
  if (typeof value !== "string") return null;
  const base = value.trim().toLowerCase().replaceAll("_", "-").split("-")[0];
  return supportedLanguageCodes.has(base) ? base : null;
}

export function detectBrowserLanguage(languageList = null) {
  const browserLanguages = languageList ?? globalThis.navigator?.languages ?? [globalThis.navigator?.language];
  for (const candidate of browserLanguages ?? []) {
    const normalized = normalizeLanguage(candidate);
    if (normalized) return normalized;
  }
  return "en";
}

export function hasSavedLanguage() {
  return Boolean(normalizeLanguage(readStorage(languageStorageKey)));
}

export function detectInitialLanguage() {
  return normalizeLanguage(readStorage(languageStorageKey)) ?? detectBrowserLanguage();
}

const supportedLanguageByCode = new Map(supportedLanguages.map((language) => [language.code, language]));

let currentLanguage = detectInitialLanguage();
let currentLocale = supportedLanguageByCode.get(currentLanguage)?.locale ?? "en-US";

function getPath(source, key) {
  return key.split(".").reduce((value, segment) => value?.[segment], source);
}

// Shortcut hints are written once as "Ctrl/⌘"; show only the key this
// device actually uses ("⌘" on Apple platforms, "Ctrl" elsewhere).
const primaryModifierLabel = (() => {
  const navigatorObject = globalThis.navigator;
  const platform = navigatorObject?.userAgentData?.platform ?? navigatorObject?.platform ?? navigatorObject?.userAgent ?? "";
  return /mac|iphone|ipad|ipod/i.test(String(platform)) ? "⌘" : "Ctrl";
})();

export function formatShortcutModifiers(text) {
  return typeof text === "string" ? text.replaceAll("Ctrl/⌘", primaryModifierLabel) : text;
}

export function t(key, variables = {}) {
  const value = getPath(translationCatalogs[currentLanguage], key) ?? getPath(translationCatalogs.en, key) ?? key;
  if (typeof value !== "string") return key;
  return formatShortcutModifiers(
    value.replace(/\{(\w+)\}/g, (match, name) => (variables[name] === undefined ? match : String(variables[name])))
  );
}

export function getLanguage() {
  return currentLanguage;
}

export function getLocale() {
  return currentLocale;
}

export function getLanguageLabel(code = currentLanguage) {
  return supportedLanguageByCode.get(normalizeLanguage(code))?.label ?? code;
}

function getIntlFormatOptionsKey(options) {
  if (!options) return "";
  const keys = Object.keys(options);
  if (!keys.length) return "";
  keys.sort();

  let result = "";
  for (const key of keys) {
    const value = options[key];
    if (value === undefined) continue;
    if (result) result += "&";
    result += `${key}=${String(value)}`;
  }
  return result;
}

const defaultNumberFormattersByLocale = new Map();
const numberFormattersByKey = new Map();

function getNumberFormatter(locale, options) {
  const optionsKey = getIntlFormatOptionsKey(options);
  if (!optionsKey) {
    let formatter = defaultNumberFormattersByLocale.get(locale);
    if (!formatter) {
      formatter = new Intl.NumberFormat(locale);
      defaultNumberFormattersByLocale.set(locale, formatter);
    }
    return formatter;
  }

  const key = `${locale}\u0000${optionsKey}`;
  let formatter = numberFormattersByKey.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options);
    numberFormattersByKey.set(key, formatter);
  }
  return formatter;
}

export function formatNumber(value, options) {
  return getNumberFormatter(currentLocale, options).format(value);
}

const regionDisplayNamesByLocale = new Map();

function getRegionDisplayNames(locale) {
  let formatter = regionDisplayNamesByLocale.get(locale);
  if (!formatter) {
    formatter = new Intl.DisplayNames([locale], { type: "region" });
    regionDisplayNamesByLocale.set(locale, formatter);
  }
  return formatter;
}

export function formatRegionName(regionCode) {
  const normalized = typeof regionCode === "string" ? regionCode.trim().toUpperCase() : "";
  if (!/^[A-Z]{2}$/.test(normalized)) return normalized;
  try {
    return getRegionDisplayNames(currentLocale).of(normalized) ?? normalized;
  } catch {
    return normalized;
  }
}

const defaultDateTimeFormattersByLocale = new Map();
const dateTimeFormattersByKey = new Map();

function getDateTimeFormatter(locale, options) {
  const optionsKey = getIntlFormatOptionsKey(options);
  if (!optionsKey) {
    let formatter = defaultDateTimeFormattersByLocale.get(locale);
    if (!formatter) {
      formatter = new Intl.DateTimeFormat(locale);
      defaultDateTimeFormattersByLocale.set(locale, formatter);
    }
    return formatter;
  }

  const key = `${locale}\u0000${optionsKey}`;
  let formatter = dateTimeFormattersByKey.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, options);
    dateTimeFormattersByKey.set(key, formatter);
  }
  return formatter;
}

export function formatDateTime(value, options) {
  return getDateTimeFormatter(currentLocale, options).format(value);
}

export function populateLanguageSelect(select) {
  if (typeof HTMLSelectElement === "undefined" || !(select instanceof HTMLSelectElement)) return;
  select.replaceChildren(
    ...supportedLanguages.map(({ code, label }) => {
      const option = document.createElement("option");
      option.value = code;
      option.textContent = label;
      return option;
    })
  );
  select.value = currentLanguage;
}

export function applyDocumentTranslations(root = globalThis.document) {
  if (!root?.querySelectorAll) return;

  root.querySelectorAll("[data-i18n]").forEach((element) => {
    // data-i18n-number fills a {number} placeholder, e.g. "Default cover 2".
    const variables = element.dataset.i18nNumber === undefined ? {} : { number: element.dataset.i18nNumber };
    element.textContent = t(element.dataset.i18n, variables);
  });
  root.querySelectorAll("[data-i18n-html]").forEach((element) => {
    element.innerHTML = t(element.dataset.i18nHtml);
  });
  root.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    element.setAttribute("placeholder", t(element.dataset.i18nPlaceholder));
  });
  root.querySelectorAll("[data-i18n-aria-label]").forEach((element) => {
    element.setAttribute("aria-label", t(element.dataset.i18nAriaLabel));
  });
  root.querySelectorAll("[data-i18n-title]").forEach((element) => {
    element.setAttribute("title", t(element.dataset.i18nTitle));
  });
  root.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    element.setAttribute("alt", t(element.dataset.i18nAlt));
  });
  root.querySelectorAll("[data-i18n-content]").forEach((element) => {
    element.setAttribute("content", t(element.dataset.i18nContent));
  });
  // Untranslated shortcut chips (e.g. the sidebar's "Ctrl/⌘ K") still name one key.
  root.querySelectorAll("kbd:not([data-i18n])").forEach((element) => {
    if (element.children.length === 0 && element.textContent.includes("Ctrl/⌘")) {
      element.textContent = formatShortcutModifiers(element.textContent);
    }
  });

  if (typeof document !== "undefined") {
    document.documentElement.lang = currentLanguage;
    document.documentElement.dir = "ltr";
    document.documentElement.dataset.language = currentLanguage;
  }
}

export function setLanguage(language, { persist = true } = {}) {
  const nextLanguage = normalizeLanguage(language) ?? "en";
  if (persist) writeStorage(languageStorageKey, nextLanguage);
  if (nextLanguage === currentLanguage) {
    applyDocumentTranslations();
    return currentLanguage;
  }

  currentLanguage = nextLanguage;
  currentLocale = supportedLanguageByCode.get(nextLanguage)?.locale ?? "en-US";
  applyDocumentTranslations();
  if (typeof globalThis.dispatchEvent === "function" && typeof CustomEvent === "function") {
    globalThis.dispatchEvent(
      new CustomEvent("brainvault:languagechange", { detail: { language: currentLanguage, locale: getLocale() } })
    );
  }
  return currentLanguage;
}

if (typeof window !== "undefined") {
  window.addEventListener("languagechange", () => {
    if (!hasSavedLanguage()) setLanguage(detectBrowserLanguage(), { persist: false });
  });
}
